     }
     #pragma omp for schedule(static)
     for (int i = 0; i < k; i++) {
         y[i] = z[i];
     }
     #pragma omp master
     {
       y[k] = alpha;
     }
     #pragma omp barrier
   }
 }
#pragma endscop


